import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 撤销观测更正附页请求：只允许撤销当前最新有效附页，撤销后恢复上一个有效版本。
 *
 * @param requestId   全局唯一请求标识（幂等去重键）
 * @param corrVersion 待撤销的附页版本号，必须是当前最新有效附页
 * @param operator    执行撤销的操作者标识
 */
public record CorrigendumRevokeRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotNull @Min(1) Integer corrVersion,
        @NotBlank @Size(max = 128) String operator) {
}

package com.example.starter.observation;

import java.time.Instant;

/**
 * 附页撤销记录：对应 corrigendum_revocation 表的一行，不可变、永不更新或删除。
 *
 * @param observationId 观测记录唯一标识
 * @param corrVersion   被撤销的附页版本号
 * @param requestId     执行撤销的请求标识
 * @param operator      执行撤销的操作者标识
 * @param revokedAtUtc  撤销完成时刻（UTC）
 */
public record RevocationRecord(
        String observationId,
        int corrVersion,
        String requestId,
        String operator,
        Instant revokedAtUtc) {
}

package com.example.starter.observation;

import java.time.Instant;

/**
 * 待复审标记：已人工裁决的观测再收到新附页时生成，对应 re_review_marker 表的一行。
 *
 * @param resolutionId  被冻结的冲突解决记录标识
 * @param observationId 观测记录唯一标识
 * @param corrVersion   触发该标记的附页版本号
 * @param status        标记状态：PENDING 表示待复审
 * @param createdAtUtc  标记生成时刻（UTC）
 */
public record ReReviewMarker(
        String resolutionId,
        String observationId,
        int corrVersion,
        String status,
        Instant createdAtUtc) {
}

